import { motion } from "framer-motion";
import { Quote } from "lucide-react";

interface Testimonial {
  id: number;
  quote: string;
  name: string;
  role: string;
  imageSrc: string;
}

interface TestimonialSectionProps {
  title: string;
  subtitle: string;
  testimonials: Testimonial[];
}

export const TestimonialSection = ({ title, subtitle, testimonials }: TestimonialSectionProps) => {
  const containerVariants = {
    hidden: {},
    visible: { transition: { staggerChildren: 0.2 } },
  };
  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: "easeOut" } },
  };

  return (
    <section className="py-20 px-6">
      <div className="max-w-6xl mx-auto text-center">
        <h2 className="text-3xl md:text-4xl font-semibold tracking-tight">{title}</h2>
        <p className="mt-3 text-muted-foreground max-w-2xl mx-auto">{subtitle}</p>

        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          className="mt-12 grid gap-6 md:grid-cols-3"
        >
          {testimonials.map((t) => (
            <motion.article
              key={t.id}
              variants={itemVariants}
              className="relative overflow-hidden rounded-3xl border border-white/40 bg-white/60 backdrop-blur-xl"
            >
              <div className="relative h-56 w-full">
                <img src={t.imageSrc} alt={t.name} className="h-full w-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-white/95 via-white/30 to-transparent" />
              </div>
              <div className="p-6 text-left">
                <Quote className="h-5 w-5 text-primary mb-3" />
                <p className="text-sm leading-relaxed">{t.quote}</p>
                <footer className="mt-4 text-sm">
                  <span className="font-semibold">— {t.name},</span>
                  <span className="text-muted-foreground"> {t.role}</span>
                </footer>
              </div>
            </motion.article>
          ))}
        </motion.div>
      </div>
    </section>
  );
};

